#!/usr/bin/env python3
"""
Applies the poster-upload + video-playback changes to the
Movie Playlist Manager project.

Usage (run from the project ROOT - the folder containing
'backend' and 'frontend'):

    cd mdm-project-main
    python apply_poster_video_changes.py

Works the same way on Windows (PowerShell / cmd), macOS, and Linux.
"""

import os
import shutil
import subprocess
import sys

FILES = {}

FILES['backend/apps/movies/models.py'] = 'from django.db import models\n\n\nclass Genre(models.Model):\n    name = models.CharField(max_length=50, unique=True)\n\n    class Meta:\n        ordering = [\'name\']\n\n    def __str__(self):\n        return self.name\n\n\nclass Person(models.Model):\n    """A real person who can appear as a director and/or as cast on many movies."""\n    name = models.CharField(max_length=200, db_index=True)\n    photo_url = models.URLField(blank=True, default=\'\')\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name_plural = \'people\'\n\n    def __str__(self):\n        return self.name\n\n\nclass Movie(models.Model):\n    VISIBILITY_PRIVATE = \'private\'\n    VISIBILITY_PUBLIC = \'public\'\n\n    VISIBILITY_CHOICES = [\n        (VISIBILITY_PRIVATE, \'Private\'),\n        (VISIBILITY_PUBLIC, \'Public\'),\n    ]\n\n    title = models.CharField(max_length=255, db_index=True)\n    description = models.TextField(blank=True, default=\'\')\n\n    # Owner of a user-uploaded movie.\n    # NULL means this is a shared/catalog movie, such as a TMDB movie.\n    owner = models.ForeignKey(\n        \'accounts.User\',\n        related_name=\'uploaded_movies\',\n        on_delete=models.CASCADE,\n        null=True,\n        blank=True,\n    )\n\n    # Actual uploaded movie/video file.\n    video_file = models.FileField(\n        upload_to=\'movies/videos/\',\n        null=True,\n        blank=True,\n    )\n\n    # Controls whether other users can view this uploaded movie.\n    visibility = models.CharField(\n        max_length=10,\n        choices=VISIBILITY_CHOICES,\n        default=VISIBILITY_PRIVATE,\n    )\n\n    release_date = models.DateField(db_index=True, null=True, blank=True)\n    poster_url = models.URLField(blank=True, default=\'\')\n    # Uploaded poster image (for user-uploaded movies). Takes priority over\n    # poster_url when both are set — see MovieListSerializer.get_poster_url.\n    poster_image = models.ImageField(\n        upload_to=\'movies/posters/\',\n        null=True,\n        blank=True,\n    )\n    backdrop_url = models.URLField(blank=True, default=\'\')\n    runtime_minutes = models.PositiveIntegerField(null=True, blank=True)\n\n    genres = models.ManyToManyField(\n        Genre,\n        related_name=\'movies\',\n        blank=True\n    )\n\n    director = models.ForeignKey(\n        Person,\n        related_name=\'directed_movies\',\n        on_delete=models.SET_NULL,\n        null=True,\n        blank=True\n    )\n\n    cast = models.ManyToManyField(\n        Person,\n        through=\'MovieCastMember\',\n        related_name=\'acted_in_movies\',\n        blank=True\n    )\n\n    rating = models.DecimalField(\n        max_digits=3,\n        decimal_places=1,\n        null=True,\n        blank=True\n    )\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'-created_at\']\n        indexes = [\n            models.Index(fields=[\'title\']),\n            models.Index(fields=[\'release_date\']),\n            models.Index(fields=[\'owner\']),\n        ]\n\n    def __str__(self):\n        return self.title\n\n    @property\n    def release_year(self):\n        return self.release_date.year if self.release_date else None\n\n\nclass MovieCastMember(models.Model):\n    """Through-model so we can keep cast ordering / character names per movie."""\n    movie = models.ForeignKey(Movie, on_delete=models.CASCADE, related_name=\'cast_members\')\n    person = models.ForeignKey(Person, on_delete=models.CASCADE, related_name=\'cast_credits\')\n    character_name = models.CharField(max_length=200, blank=True, default=\'\')\n    billing_order = models.PositiveSmallIntegerField(default=0)\n\n    class Meta:\n        ordering = [\'billing_order\']\n        unique_together = [\'movie\', \'person\']\n\n    def __str__(self):\n        return f\'{self.person} in {self.movie}\'\n'

FILES['backend/apps/movies/serializers.py'] = 'from rest_framework import serializers\n\nfrom .models import Genre, Movie, MovieCastMember, Person\n\n\nclass GenreSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Genre\n        fields = [\'id\', \'name\']\n\n\nclass PersonSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Person\n        fields = [\'id\', \'name\', \'photo_url\']\n\n\nclass CastMemberSerializer(serializers.ModelSerializer):\n    """\n    Cast entry as seen from a movie.\n    """\n\n    id = serializers.IntegerField(\n        source=\'person.id\',\n        read_only=True\n    )\n\n    name = serializers.CharField(\n        source=\'person.name\',\n        read_only=True\n    )\n\n    photo_url = serializers.URLField(\n        source=\'person.photo_url\',\n        read_only=True\n    )\n\n    class Meta:\n        model = MovieCastMember\n        fields = [\n            \'id\',\n            \'name\',\n            \'photo_url\',\n            \'character_name\',\n            \'billing_order\',\n        ]\n\n\nclass MovieListSerializer(serializers.ModelSerializer):\n    """\n    Lightweight representation used by movie list/grid pages.\n    """\n\n    genres = GenreSerializer(\n        many=True,\n        read_only=True\n    )\n\n    director = PersonSerializer(\n        read_only=True\n    )\n\n    release_year = serializers.IntegerField(\n        read_only=True\n    )\n\n    # If the user uploaded a poster image, serve that. Otherwise fall back\n    # to the plain poster_url (e.g. a catalog/TMDB image link).\n    poster_url = serializers.SerializerMethodField()\n\n    def get_poster_url(self, obj):\n        if obj.poster_image:\n            request = self.context.get(\'request\')\n            url = obj.poster_image.url\n            return request.build_absolute_uri(url) if request else url\n        return obj.poster_url or \'\'\n\n    # Information about the user who uploaded the movie.\n    owner_id = serializers.IntegerField(\n        source=\'owner.id\',\n        read_only=True\n    )\n\n    owner_username = serializers.CharField(\n        source=\'owner.username\',\n        read_only=True,\n        allow_null=True\n    )\n\n    # Actual uploaded video file.\n    video_file = serializers.FileField(\n        read_only=True\n    )\n\n    # private / public\n    visibility = serializers.CharField(\n        read_only=True\n    )\n\n    # User-specific library information.\n    is_favorited = serializers.SerializerMethodField()\n    is_in_watchlist = serializers.SerializerMethodField()\n    is_watched = serializers.SerializerMethodField()\n\n    class Meta:\n        model = Movie\n\n        fields = [\n            \'id\',\n            \'title\',\n            \'description\',\n            \'poster_url\',\n            \'backdrop_url\',\n            \'release_date\',\n            \'release_year\',\n            \'runtime_minutes\',\n            \'rating\',\n            \'genres\',\n            \'director\',\n\n            # Uploaded movie information\n            \'owner_id\',\n            \'owner_username\',\n            \'video_file\',\n            \'visibility\',\n\n            # User library information\n            \'is_favorited\',\n            \'is_in_watchlist\',\n            \'is_watched\',\n        ]\n\n    def _user(self):\n        request = self.context.get(\'request\')\n\n        user = getattr(\n            request,\n            \'user\',\n            None\n        )\n\n        return (\n            user\n            if user and user.is_authenticated\n            else None\n        )\n\n    def get_is_favorited(self, obj):\n        user = self._user()\n\n        if user is None:\n            return False\n\n        ids = self.context.get(\n            \'favorited_movie_ids\'\n        )\n\n        if ids is not None:\n            return obj.id in ids\n\n        return obj.favorited_by.filter(\n            user=user\n        ).exists()\n\n    def get_is_in_watchlist(self, obj):\n        user = self._user()\n\n        if user is None:\n            return False\n\n        ids = self.context.get(\n            \'watchlisted_movie_ids\'\n        )\n\n        if ids is not None:\n            return obj.id in ids\n\n        return obj.on_watchlists.filter(\n            user=user\n        ).exists()\n\n    def get_is_watched(self, obj):\n        user = self._user()\n\n        if user is None:\n            return False\n\n        ids = self.context.get(\n            \'watched_movie_ids\'\n        )\n\n        if ids is not None:\n            return obj.id in ids\n\n        return obj.watched_by.filter(\n            user=user\n        ).exists()\n\n\nclass MovieDetailSerializer(MovieListSerializer):\n    """\n    Full representation used by the movie detail page.\n    """\n\n    cast_members = CastMemberSerializer(\n        many=True,\n        read_only=True\n    )\n\n    my_rating = serializers.SerializerMethodField()\n\n    class Meta(MovieListSerializer.Meta):\n        fields = MovieListSerializer.Meta.fields + [\n            \'cast_members\',\n            \'created_at\',\n            \'updated_at\',\n            \'my_rating\',\n        ]\n\n    def get_my_rating(self, obj):\n        user = self._user()\n\n        if user is None:\n            return None\n\n        rating = obj.ratings.filter(\n            user=user\n        ).first()\n\n        if rating is None:\n            return None\n\n        return {\n            \'score\': rating.score,\n            \'review\': rating.review,\n        }\n\n\nclass MovieWriteSerializer(serializers.ModelSerializer):\n    """\n    Serializer used by authenticated users to create and update\n    their own uploaded movies.\n\n    The owner is NOT supplied by the frontend.\n    The view will automatically assign request.user as the owner.\n    """\n\n    genre_ids = serializers.PrimaryKeyRelatedField(\n        source=\'genres\',\n        queryset=Genre.objects.all(),\n        many=True,\n        required=False\n    )\n\n    director_id = serializers.PrimaryKeyRelatedField(\n        source=\'director\',\n        queryset=Person.objects.all(),\n        required=False,\n        allow_null=True\n    )\n\n    video_file = serializers.FileField(\n        required=False,\n        allow_null=True\n    )\n\n    poster_image = serializers.ImageField(\n        required=False,\n        allow_null=True\n    )\n\n    visibility = serializers.ChoiceField(\n        choices=Movie.VISIBILITY_CHOICES,\n        required=False,\n        default=Movie.VISIBILITY_PRIVATE\n    )\n\n    class Meta:\n        model = Movie\n\n        fields = [\n            \'id\',\n            \'title\',\n            \'description\',\n            \'release_date\',\n            \'poster_url\',\n            \'poster_image\',\n            \'backdrop_url\',\n            \'runtime_minutes\',\n            \'rating\',\n\n            # Uploaded video\n            \'video_file\',\n\n            # Private/public\n            \'visibility\',\n\n            # Relationships\n            \'genre_ids\',\n            \'director_id\',\n        ]\n\n        read_only_fields = [\n            \'id\',\n        ]'

FILES['frontend/app/(app)/movies/add/page.tsx'] = '\'use client\';\n\nimport { useState, type FormEvent } from \'react\';\nimport { useRouter } from \'next/navigation\';\nimport Link from \'next/link\';\nimport { moviesApi } from \'@/lib/endpoints\';\nimport { ApiRequestError } from \'@/lib/api\';\nimport { Button } from \'@/components/ui/Button\';\nimport { Input } from \'@/components/ui/Input\';\n\nexport default function AddMoviePage() {\n  const router = useRouter();\n\n  const [title, setTitle] = useState(\'\');\n  const [description, setDescription] = useState(\'\');\n  const [releaseDate, setReleaseDate] = useState(\'\');\n  const [runtime, setRuntime] = useState(\'\');\n  const [rating, setRating] = useState(\'\');\n  const [posterUrl, setPosterUrl] = useState(\'\');\n  const [posterImage, setPosterImage] = useState<File | null>(null);\n  const [backdropUrl, setBackdropUrl] = useState(\'\');\n  const [visibility, setVisibility] = useState<\'public\' | \'private\'>(\'private\');\n  const [videoFile, setVideoFile] = useState<File | null>(null);\n\n  const [error, setError] = useState(\'\');\n  const [isSubmitting, setIsSubmitting] = useState(false);\n\n  async function handleSubmit(e: FormEvent<HTMLFormElement>) {\n    e.preventDefault();\n\n    setError(\'\');\n\n    if (!videoFile) {\n      setError(\'Please select a video file.\');\n      return;\n    }\n\n    if (!title.trim()) {\n      setError(\'Please enter a movie title.\');\n      return;\n    }\n\n    const formData = new FormData();\n\n    formData.append(\'title\', title);\n    formData.append(\'description\', description);\n    formData.append(\'visibility\', visibility);\n\n    if (releaseDate) {\n      formData.append(\'release_date\', releaseDate);\n    }\n\n    if (runtime) {\n      formData.append(\'runtime_minutes\', runtime);\n    }\n\n    if (rating) {\n      formData.append(\'rating\', rating);\n    }\n\n    // An uploaded poster image takes priority over a pasted URL (enforced\n    // on the backend too), so only send the URL when there\'s no file.\n    if (posterImage) {\n      formData.append(\'poster_image\', posterImage);\n    } else if (posterUrl) {\n      formData.append(\'poster_url\', posterUrl);\n    }\n\n    if (backdropUrl) {\n      formData.append(\'backdrop_url\', backdropUrl);\n    }\n\n    formData.append(\'video_file\', videoFile);\n\n    setIsSubmitting(true);\n\n    try {\n      await moviesApi.create(formData);\n\n      router.push(\'/movies/my\');\n      router.refresh();\n    } catch (err) {\n      if (err instanceof ApiRequestError) {\n        const body = err.body;\n\n        if (body.detail) {\n          setError(body.detail);\n        } else {\n          const firstError = Object.values(body)[0];\n\n          if (Array.isArray(firstError)) {\n            setError(String(firstError[0]));\n          } else {\n            setError(String(firstError ?? \'Failed to upload movie.\'));\n          }\n        }\n      } else {\n        setError(\'Failed to upload movie.\');\n      }\n    } finally {\n      setIsSubmitting(false);\n    }\n  }\n\n  return (\n    <main className="min-h-screen bg-background px-4 py-10">\n      <div className="mx-auto max-w-2xl">\n        <div className="mb-8">\n          <Link\n            href="/movies/my"\n            className="text-sm text-foreground-muted hover:text-foreground"\n          >\n            ← Back to My Movies\n          </Link>\n\n          <h1 className="mt-4 font-display text-3xl font-medium text-foreground">\n            Add Movie\n          </h1>\n\n          <p className="mt-2 text-sm text-foreground-muted">\n            Upload a movie to your personal library.\n          </p>\n        </div>\n\n        <form\n          onSubmit={handleSubmit}\n          className="flex flex-col gap-5 rounded-xl border border-border bg-card p-6"\n        >\n          <Input\n            label="Movie title"\n            value={title}\n            onChange={(e) => setTitle(e.target.value)}\n            required\n          />\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Description\n            </label>\n\n            <textarea\n              value={description}\n              onChange={(e) => setDescription(e.target.value)}\n              rows={5}\n              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground outline-none focus:border-accent"\n              placeholder="Enter a description..."\n            />\n          </div>\n\n          <Input\n            label="Release date"\n            type="date"\n            value={releaseDate}\n            onChange={(e) => setReleaseDate(e.target.value)}\n          />\n\n          <Input\n            label="Runtime (minutes)"\n            type="number"\n            min="1"\n            value={runtime}\n            onChange={(e) => setRuntime(e.target.value)}\n          />\n\n          <Input\n            label="Rating"\n            type="number"\n            min="0"\n            max="10"\n            step="0.1"\n            value={rating}\n            onChange={(e) => setRating(e.target.value)}\n          />\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Poster image\n            </label>\n\n            <input\n              type="file"\n              accept="image/*"\n              onChange={(e) => {\n                setPosterImage(e.target.files?.[0] ?? null);\n              }}\n              className="block w-full rounded-lg border border-border bg-background p-3 text-sm text-foreground"\n            />\n\n            {posterImage && (\n              <p className="mt-2 text-xs text-foreground-muted">\n                Selected: {posterImage.name}\n              </p>\n            )}\n          </div>\n\n          <Input\n            label="Poster URL"\n            type="url"\n            value={posterUrl}\n            onChange={(e) => setPosterUrl(e.target.value)}\n            placeholder="https://... (ignored if you upload an image above)"\n            disabled={!!posterImage}\n          />\n\n          <Input\n            label="Backdrop URL"\n            type="url"\n            value={backdropUrl}\n            onChange={(e) => setBackdropUrl(e.target.value)}\n            placeholder="https://..."\n          />\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Video file\n            </label>\n\n            <input\n              type="file"\n              accept="video/*"\n              onChange={(e) => {\n                setVideoFile(e.target.files?.[0] ?? null);\n              }}\n              className="block w-full rounded-lg border border-border bg-background p-3 text-sm text-foreground"\n              required\n            />\n\n            {videoFile && (\n              <p className="mt-2 text-xs text-foreground-muted">\n                Selected: {videoFile.name}\n              </p>\n            )}\n          </div>\n\n          <div>\n            <label className="mb-2 block text-sm font-medium text-foreground">\n              Visibility\n            </label>\n\n            <select\n              value={visibility}\n              onChange={(e) =>\n                setVisibility(e.target.value as \'public\' | \'private\')\n              }\n              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground"\n            >\n              <option value="private">\n                Private — only I can see it\n              </option>\n\n              <option value="public">\n                Public — other users can see it\n              </option>\n            </select>\n          </div>\n\n          {error && (\n            <div className="rounded-lg border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">\n              {error}\n            </div>\n          )}\n\n          <Button\n            type="submit"\n            isLoading={isSubmitting}\n            className="w-full justify-center"\n          >\n            Upload Movie\n          </Button>\n        </form>\n      </div>\n    </main>\n  );\n}'

FILES['frontend/app/(app)/movies/[id]/page.tsx'] = '\'use client\';\n\nimport { use, useEffect, useState } from \'react\';\nimport Link from \'next/link\';\nimport Image from \'next/image\';\nimport { ArrowLeft, Heart, ListPlus, CheckCircle2, Bookmark, Star } from \'lucide-react\';\nimport { moviesApi, libraryApi } from \'@/lib/endpoints\';\nimport { useToast } from \'@/hooks/useToast\';\nimport { formatRuntime, formatYear, getErrorMessage } from \'@/lib/utils\';\nimport type { Movie } from \'@/types\';\nimport { Button } from \'@/components/ui/Button\';\nimport { StarRating } from \'@/components/ui/StarRating\';\nimport { Textarea } from \'@/components/ui/Input\';\nimport { AddToPlaylistModal } from \'@/components/playlists/AddToPlaylistModal\';\nimport { Skeleton } from \'@/components/ui/Skeleton\';\n\nexport default function MovieDetailPage({ params }: { params: Promise<{ id: string }> }) {\n  const { id } = use(params);\n  const movieId = Number(id);\n  const { showToast } = useToast();\n\n  const [movie, setMovie] = useState<Movie | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [playlistModalOpen, setPlaylistModalOpen] = useState(false);\n\n  const [isFavorited, setIsFavorited] = useState(false);\n  const [isWatched, setIsWatched] = useState(false);\n  const [isOnWatchlist, setIsOnWatchlist] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n\n  const [ratingScore, setRatingScore] = useState(0);\n  const [review, setReview] = useState(\'\');\n  const [savingRating, setSavingRating] = useState(false);\n\n  useEffect(() => {\n    let cancelled = false;\n    moviesApi\n      .detail(movieId)\n      .then((data) => {\n        if (cancelled) return;\n        setMovie(data);\n        setIsFavorited(data.is_favorited);\n        setIsWatched(data.is_watched);\n        setIsOnWatchlist(data.is_in_watchlist);\n        if (data.my_rating) {\n          setRatingScore(data.my_rating.score);\n          setReview(data.my_rating.review);\n        }\n      })\n      .catch((err) => !cancelled && setError(getErrorMessage(err)));\n    return () => {\n      cancelled = true;\n    };\n  }, [movieId]);\n\n  async function toggleFavorite() {\n    if (busy) return;\n    setBusy(\'favorite\');\n    const next = !isFavorited;\n    setIsFavorited(next);\n    try {\n      if (next) {\n        await libraryApi.addFavorite(movieId);\n      } else {\n        await libraryApi.removeFavorite(movieId);\n      }\n    } catch (err) {\n      setIsFavorited(!next);\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function toggleWatched() {\n    if (busy) return;\n    setBusy(\'watched\');\n    const next = !isWatched;\n    setIsWatched(next);\n    try {\n      if (next) {\n        await libraryApi.markWatched(movieId);\n      } else {\n        await libraryApi.markUnwatched(movieId);\n      }\n    } catch (err) {\n      setIsWatched(!next);\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function toggleWatchlist() {\n    if (busy) return;\n    setBusy(\'watchlist\');\n    const next = !isOnWatchlist;\n    setIsOnWatchlist(next);\n    try {\n      if (next) {\n        await libraryApi.addToWatchlist(movieId);\n      } else {\n        await libraryApi.removeFromWatchlist(movieId);\n      }\n    } catch (err) {\n      setIsOnWatchlist(!next);\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function saveRating() {\n    if (ratingScore === 0) {\n      showToast(\'Pick a star rating first.\', \'error\');\n      return;\n    }\n    setSavingRating(true);\n    try {\n      await libraryApi.rateMovie(movieId, { score: ratingScore, review });\n      showToast(\'Rating saved.\', \'success\');\n    } catch (err) {\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setSavingRating(false);\n    }\n  }\n\n  if (error) {\n    return (\n      <div className="mx-auto max-w-4xl">\n        <p className="rounded-lg border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">{error}</p>\n      </div>\n    );\n  }\n\n  if (!movie) {\n    return (\n      <div className="mx-auto max-w-5xl">\n        <Skeleton className="h-64 w-full" />\n        <div className="mt-6 flex gap-6">\n          <Skeleton className="h-72 w-48 shrink-0" />\n          <div className="flex-1 space-y-3">\n            <Skeleton className="h-8 w-2/3" />\n            <Skeleton className="h-4 w-1/3" />\n            <Skeleton className="h-24 w-full" />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div className="mx-auto max-w-5xl pb-16">\n      <Link href="/movies" className="inline-flex items-center gap-1.5 text-sm text-foreground-muted hover:text-foreground">\n        <ArrowLeft size={15} /> Back to movies\n      </Link>\n\n      {/* Player (for a movie you uploaded yourself) or backdrop */}\n      {movie.video_file ? (\n        <div className="mt-4 aspect-video w-full overflow-hidden rounded-xl bg-black">\n          <video\n            controls\n            className="h-full w-full"\n            poster={movie.poster_url || undefined}\n            src={movie.video_file}\n          >\n            Your browser doesn&apos;t support video playback.\n          </video>\n        </div>\n      ) : (\n        <div className="relative mt-4 aspect-[21/9] w-full overflow-hidden rounded-xl bg-surface">\n          {movie.backdrop_url ? (\n            <Image src={movie.backdrop_url} alt="" fill sizes="100vw" className="object-cover" priority />\n          ) : null}\n          <div className="absolute inset-0 bg-gradient-to-t from-background via-background/40 to-transparent" />\n        </div>\n      )}\n\n      <div\n        className={`flex flex-col gap-6 px-2 sm:flex-row sm:px-4 ${\n          movie.video_file ? \'mt-6\' : \'-mt-20\'\n        }`}\n      >\n        {/* Poster */}\n        <div className="relative aspect-[2/3] w-40 shrink-0 overflow-hidden rounded-lg border border-border bg-surface shadow-xl sm:w-52">\n          {movie.poster_url ? (\n            <Image src={movie.poster_url} alt={movie.title} fill sizes="208px" className="object-cover" />\n          ) : (\n            <div className="flex h-full items-center justify-center text-xs text-foreground-muted">No poster</div>\n          )}\n        </div>\n\n        <div className="flex-1 pt-2 sm:pt-16">\n          <h1 className="font-display text-2xl font-medium text-foreground sm:text-3xl">{movie.title}</h1>\n          <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 font-mono text-sm text-foreground-muted">\n            <span>{formatYear(movie.release_date)}</span>\n            <span>•</span>\n            <span>{formatRuntime(movie.runtime_minutes)}</span>\n            {movie.genres.length > 0 && (\n              <>\n                <span>•</span>\n                <span>{movie.genres.map((g) => g.name).join(\' / \')}</span>\n              </>\n            )}\n            {movie.rating && (\n              <>\n                <span>•</span>\n                <span className="flex items-center gap-1 text-warning">\n                  <Star size={13} className="fill-warning" /> {movie.rating}\n                </span>\n              </>\n            )}\n          </div>\n\n          {movie.description && <p className="mt-4 max-w-2xl text-sm leading-relaxed text-foreground-muted">{movie.description}</p>}\n\n          {movie.director && <p className="mt-4 text-sm text-foreground">\n            <span className="text-foreground-muted">Director: </span>{movie.director.name}\n          </p>}\n\n          {movie.cast_members && movie.cast_members.length > 0 && (\n            <div className="mt-2 text-sm text-foreground">\n              <span className="text-foreground-muted">Cast: </span>\n              {movie.cast_members\n                .slice()\n                .sort((a, b) => a.billing_order - b.billing_order)\n                .map((c) => c.name)\n                .join(\', \')}\n            </div>\n          )}\n\n          <div className="mt-6 flex flex-wrap gap-2">\n            <Button\n              variant={isWatched ? \'primary\' : \'secondary\'}\n              onClick={toggleWatched}\n              isLoading={busy === \'watched\'}\n            >\n              <CheckCircle2 size={16} /> {isWatched ? \'Watched\' : \'Mark watched\'}\n            </Button>\n            <Button\n              variant={isOnWatchlist ? \'primary\' : \'secondary\'}\n              onClick={toggleWatchlist}\n              isLoading={busy === \'watchlist\'}\n            >\n              <Bookmark size={16} /> {isOnWatchlist ? \'On watchlist\' : \'Add to watchlist\'}\n            </Button>\n            <Button variant="secondary" onClick={() => setPlaylistModalOpen(true)}>\n              <ListPlus size={16} /> Add to playlist\n            </Button>\n            <Button\n              variant={isFavorited ? \'primary\' : \'secondary\'}\n              onClick={toggleFavorite}\n              isLoading={busy === \'favorite\'}\n            >\n              <Heart size={16} className={isFavorited ? \'fill-current\' : \'\'} /> Favorite\n            </Button>\n          </div>\n        </div>\n      </div>\n\n      {/* Personal rating + review */}\n      <div className="mt-10 max-w-2xl rounded-xl border border-border bg-surface p-5">\n        <h2 className="font-display text-lg font-medium text-foreground">Your rating</h2>\n        <div className="mt-3">\n          <StarRating value={ratingScore} onChange={setRatingScore} />\n        </div>\n        <Textarea\n          label="Your review"\n          value={review}\n          onChange={(e) => setReview(e.target.value)}\n          placeholder="What did you think?"\n          rows={3}\n          className="mt-4"\n        />\n        <Button className="mt-3" onClick={saveRating} isLoading={savingRating}>\n          Save review\n        </Button>\n      </div>\n\n      <AddToPlaylistModal\n        isOpen={playlistModalOpen}\n        onClose={() => setPlaylistModalOpen(false)}\n        movieId={movie.id}\n        movieTitle={movie.title}\n      />\n    </div>\n  );\n}\n'

