def main():
    root = os.getcwd()
    if not os.path.isdir(os.path.join(root, 'backend')) or not os.path.isdir(os.path.join(root, 'frontend')):
        print('Error: run this script from the project root (must contain backend/ and frontend/ folders).')
        sys.exit(1)

    print('Backing up files that will be changed (.bak)...')
    for rel_path in FILES:
        full_path = os.path.join(root, rel_path)
        if os.path.exists(full_path):
            shutil.copyfile(full_path, full_path + '.bak')

    for rel_path, content in FILES.items():
        full_path = os.path.join(root, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        print(f'Writing {rel_path}...')
        with open(full_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)

    print('Running Django migration...')
    backend_dir = os.path.join(root, 'backend')
    venv_python_candidates = [
        os.path.join(backend_dir, 'venv', 'Scripts', 'python.exe'),  # Windows venv
        os.path.join(backend_dir, 'venv', 'bin', 'python'),          # macOS/Linux venv
    ]
    python_bin = next((p for p in venv_python_candidates if os.path.exists(p)), None)
    if python_bin is None:
        python_bin = sys.executable
        print('Warning: no venv found at backend/venv, using the current Python interpreter.')

    result = subprocess.run([python_bin, 'manage.py', 'migrate'], cwd=backend_dir)
    if result.returncode != 0:
        print('Migration failed - see the error above. Your source files were already updated.')
        sys.exit(result.returncode)

    print()
    print('Done. Poster upload + video playback changes applied.')
    print('Backups of the original files were saved alongside them as *.bak')
    print('(delete them once you have confirmed everything works)')

if __name__ == '__main__':
    main()
